from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.board = [
            line.lstrip().split()
            for line in board.splitlines()
            if line.strip()
        ]
        self.size = len(self.board)

    def get_winner(self):
        if self._wins("X"):
            return "X"
        if self._wins("O"):
            return "O"
        return ""

    def _wins(self, player):
        # X connects left to right, O connects top to bottom.
        if player == "X":
            start = {(r, c) for r, row in enumerate(self.board)
                     for c in (0, len(row) - 1)}
            goal = lambda r, c: c == len(self.board[r]) - 1
        else:
            start = {(r, c) for r, c in self._edge_cells(0)}
            goal = lambda r, c: r == self.size - 1

        start = {cell for cell in start if self.board[cell[0]][cell[1]] == player}
        if not start:
            return False

        seen = set(start)
        queue = deque(start)
        while queue:
            r, c = queue.popleft()
            if goal(r, c):
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in seen and self.board[nr][nc] == player:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def _edge_cells(self, r):
        for c in range(len(self.board[r])):
            yield r, c

    def _neighbors(self, r, c):
        for nr, nc in ((r, c - 1), (r, c + 1),
                       (r - 1, c - 1), (r - 1, c),
                       (r + 1, c), (r + 1, c + 1)):
            if 0 <= nr < self.size and 0 <= nc < len(self.board[nr]):
                yield nr, nc

